import axios, { AxiosError, type AxiosAdapter, type AxiosResponse, type InternalAxiosRequestConfig } from "axios";

import globalConfig from "@/config";
import type { Manifest, Panel, PanelSummary, ReviewResult } from "@/types";

// There is no backend: an axios adapter answers the /api routes in the browser, from
// static JSON generated by scripts/build-data.mjs. The hooks, React Query caching and error handling are
// unaware of it. Responses behave like a real API, including 404 and 422 errors with a `detail` body.

const dataUrl = (file: string) => `${import.meta.env.BASE_URL}data/${file}`;

const cache = new Map<string, Promise<unknown>>();
const load = <T>(file: string): Promise<T> => {
    if (!cache.has(file)) {
        const request = fetch(dataUrl(file)).then((r) => {
            if (!r.ok) throw new Error(`${file}: HTTP ${r.status}`);
            return r.json();
        });
        // a failed fetch is not cached, so the next request retries it
        request.catch(() => cache.delete(file));
        cache.set(file, request);
    }
    return cache.get(file) as Promise<T>;
};

class HttpError extends Error {
    constructor(
        readonly status: number,
        readonly detail: string
    ) {
        super(detail);
    }
}

const isoDate = /^\d{4}-\d{2}-\d{2}$/;

async function listPanels(params: Record<string, unknown>) {
    const siteId = String(params.site_id ?? "");
    const start = String(params.start ?? "");
    const end = String(params.end ?? "");
    const offset = Number(params.offset ?? 0);
    const limit = Number(params.limit ?? 25);
    if (!isoDate.test(start) || !isoDate.test(end)) throw new HttpError(422, "start and end must be dates (yyyy-MM-dd)");
    // the same checks as PanelDataset.list_panel_summaries
    if (start >= end) throw new HttpError(422, "start must be before end");
    if (!Number.isInteger(offset) || offset < 0 || !Number.isInteger(limit) || limit < 1 || limit > 100) {
        throw new HttpError(422, "offset must be non-negative; limit must be between 1 and 100");
    }
    // summaries.json is already sorted by date then ID; the end date is exclusive
    const rows = (await load<PanelSummary[]>("summaries.json")).filter(
        (p) => p.site_id === siteId && p.collection_date >= start && p.collection_date < end
    );
    return { panels: rows.slice(offset, offset + limit), total_panels: rows.length };
}

async function getPanel(panelId: string) {
    const summary = (await load<PanelSummary[]>("summaries.json")).find((p) => p.panel_id === panelId);
    const panel = summary && (await load<Panel[]>(`panels/${summary.site_id}.json`)).find((p) => p.panel_id === panelId);
    if (!panel) throw new HttpError(404, `Unknown panel: ${panelId}`);
    return panel;
}

async function route(path: string, params: Record<string, unknown>): Promise<unknown> {
    if (path === "/manifest") return load<Manifest>("manifest.json");
    if (path === "/review") return load<ReviewResult>("review.json");
    if (path === "/panels") return listPanels(params);
    const match = /^\/panels\/([^/]+)$/.exec(path);
    if (match) return getPanel(decodeURIComponent(match[1]));
    throw new HttpError(404, "Not Found");
}

const staticAdapter: AxiosAdapter = async (config: InternalAxiosRequestConfig) => {
    const prefix = globalConfig.urls.gateway.general;
    const url = config.url ?? "";
    const path = url.startsWith(prefix) ? url.slice(prefix.length) : url;
    const respond = (status: number, data: unknown): AxiosResponse => ({
        data,
        status,
        statusText: status === 200 ? "OK" : "Error",
        headers: {},
        config,
        request: {}
    });

    try {
        return respond(200, await route(path, (config.params ?? {}) as Record<string, unknown>));
    } catch (e) {
        if (e instanceof HttpError) {
            const response = respond(e.status, { detail: e.detail });
            throw new AxiosError(e.detail, AxiosError.ERR_BAD_REQUEST, config, null, response);
        }
        // a missing or unreadable data file looks like a network failure: no response, no status
        throw new AxiosError(e instanceof Error ? e.message : "Request failed", AxiosError.ERR_NETWORK, config);
    }
};

/** Route every axios request through the static data instead of the network. */
export function installStaticGateway() {
    axios.defaults.adapter = staticAdapter;
}
